from app import attempt

for budget in (1, 2, 5):
    calls = []
    error = RuntimeError('failure')
    def fail():
        calls.append(1)
        raise error
    try:
        attempt(fail, budget)
    except RuntimeError as exc:
        assert exc is error
    else:
        raise AssertionError('Expected failure')
    assert len(calls) == budget

for succeed_on in (1, 3):
    calls = []
    result = object()
    def succeed():
        calls.append(1)
        if len(calls) < succeed_on:
            raise RuntimeError('retry')
        return result
    assert attempt(succeed, 3) is result
    assert len(calls) == succeed_on

for budget in (0, -1):
    calls = []
    try:
        attempt(lambda: calls.append(1), budget)
    except ValueError as exc:
        assert str(exc) == 'max_attempts must be positive'
    else:
        raise AssertionError('Expected validation error')
    assert not calls
print('Budget, success, and validation checks passed')
